sections.code:
provider "aws" {
  region = var.region
}

resource "aws_vpc" "main" {
  cidr_block           = "10.0.0.0/16"
  enable_dns_hostnames = true
  tags                 = { Name = "${var.env}-vpc" }
}

# The reference below is an implicit dependency: the subnet
# cannot be created before the VPC that supplies vpc_id.
resource "aws_subnet" "app" {
  vpc_id     = aws_vpc.main.id
  cidr_block = cidrsubnet(aws_vpc.main.cidr_block, 8, 1)
}

terraform {
  required_version = ">= 1.5.0"
  required_providers {
    aws = { source = "hashicorp/aws", version = "~> 5.40" }  # >= 5.40.0, < 6.0.0
  }
}

provider "aws" { region = "eu-west-1" }

provider "aws" {
  alias  = "us_east_1"
  region = "us-east-1"
}

resource "aws_acm_certificate" "cdn" {
  provider = aws.us_east_1   # CloudFront certificates must live in us-east-1
}

data "aws_ami" "al2023" {
  most_recent = true
  owners      = ["amazon"]
  filter {
    name   = "name"
    values = ["al2023-ami-*-x86_64"]
  }
}

data "terraform_remote_state" "network" {
  backend = "s3"
  config = {
    bucket = "acme-tfstate-prod"
    key    = "network/terraform.tfstate"
    region = "us-east-1"
  }
}

resource "aws_instance" "web" {
  ami       = data.aws_ami.al2023.id
  subnet_id = data.terraform_remote_state.network.outputs.private_subnet_ids[0]
}

variable "env" {
  type        = string
  description = "Deployment environment"
  validation {
    condition     = contains(["dev", "stage", "prod"], var.env)
    error_message = "env must be one of dev, stage, prod."
  }
}

variable "db_password" {
  type      = string
  sensitive = true      # redacted in CLI output, still plaintext in state
}

locals {
  name_prefix = "${var.env}-payments"
  common_tags = merge(var.tags, { Environment = var.env })
}

output "vpc_id" {
  value = aws_vpc.main.id
}

terraform {
  backend "s3" {
    bucket         = "acme-tfstate-prod"
    key            = "network/terraform.tfstate"
    region         = "us-east-1"
    encrypt        = true
    dynamodb_table = "terraform-locks"   # classic S3 locking mechanism
  }
}

resource "aws_dynamodb_table" "locks" {
  name         = "terraform-locks"
  billing_mode = "PAY_PER_REQUEST"
  hash_key     = "LockID"                # required partition key name
  attribute { name = "LockID", type = "S" }
}

# Partial configuration keeps per-environment values out of the code
terraform init -backend-config=envs/prod/backend.hcl -reconfigure
terraform init -migrate-state      # when moving state between backends

module "vpc" {
  source  = "terraform-aws-modules/vpc/aws"
  version = "~> 5.0"

  name = "${var.env}-vpc"
  cidr = "10.0.0.0/16"
}

module "app" {
  source     = "git::https://github.com/acme/tf-modules.git//app?ref=v1.4.2"
  vpc_id     = module.vpc.vpc_id
  subnet_ids = module.vpc.private_subnets
}

resource "aws_instance" "worker" {
  count         = var.worker_count       # aws_instance.worker[0], [1], ...
  instance_type = "t3.small"
  tags          = { Name = "worker-${count.index}" }
}

resource "aws_subnet" "app" {
  for_each          = var.subnet_cidrs   # map(string); keys known at plan time
  vpc_id            = aws_vpc.main.id
  availability_zone = each.key           # aws_subnet.app["us-east-1a"]
  cidr_block        = each.value
}

moved {
  from = aws_subnet.app[0]
  to   = aws_subnet.app["us-east-1a"]
}

resource "aws_launch_template" "api" {
  name_prefix = "api-"          # required: old and new must coexist
  lifecycle {
    create_before_destroy = true
  }
}

resource "aws_db_instance" "primary" {
  lifecycle {
    prevent_destroy = true
    ignore_changes  = [engine_version]   # patched out of band by the DBA team
  }
}

resource "aws_instance" "app" {
  lifecycle {
    replace_triggered_by = [aws_launch_template.api.latest_version]
  }
}
